SourceCode.Declaration:
public class ReaLoop
{
    int counter;
    str label;
    container items;
}

Method.Source:
public void new(str _label)
{
    label = _label;
    counter = 0;
    items = conNull();
}

public int countTo(int _limit)
{
    int i;
    for (i = 1; i <= _limit; i++)
    {
        if (i mod 2 == 0)
        {
            counter += i;
        }
        else
        {
            items = conIns(items, conLen(items) + 1, i);
        }
    }
    while (counter > 100)
    {
        counter = counter div 2;
    }
    return counter;
}

public str describe()
{
    return ReaHello::greet(label) + ' / ' + int2Str(conLen(items));
}

public static ReaLoop construct(str _label)
{
    ReaLoop loop = new ReaLoop(_label);
    return loop;
}
